def compute(vars):
    net_interest_revenue = vars["v1"]
    total_operating_expenses = vars["v2"]

    if net_interest_revenue == 0:
        return None

    ratio = total_operating_expenses / net_interest_revenue
    value = ratio * 100

    return {
        "value": value,
        "trace": {
            "net_interest_revenue": net_interest_revenue,
            "total_operating_expenses": total_operating_expenses,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
